export interface InternalRoute {
    /**
     * The route to pass to the navigate function. May differ from routeWithBaseHref because some navigate
     * functions may apply the base href themselves.
     */
    routeToNavigate: string;
    /**
     * The route to navigate with the base href applied. This is used for anchor tags to open in new tab, display the route, etc.
     */
    routeWithBaseHref: string;
    /**
     * A framework specific function to call to navigate to the route. The routeToNavigate property will be passed to it.
     */
    navigateFn: (_: string) => any;
}
